-- ==============================================================================================================
-- WabiBankPersonnelDB — Wabi Bank personnel, structure, attendance, leave and identities (sample)
-- Divisions, Head Office departments and branches, sections, employees, transfers, leave, daily attendance, system users and access, 2025.
--
-- What this script does (run it as a sysadmin, in SSMS or sqlcmd):
--   1. creates the database [WabiBankPersonnelDB] if it does not exist;
--   2. creates the owner login [wbpersonnel_owner] (db_owner) and the read-only login [wbpersonnel_reader] (db_datareader),
--      which is the one to register in Wabi Insight (Applications > connection string);
--   3. drops and recreates every sample table, loads the reference data and generates calendar year 2025.
-- Re-running resets the sample data. Change both passwords below before using this outside a sandbox.
-- The data is synthetic and deterministic (same numbers on every run). Generated by build_sample_sql.py.
-- ==============================================================================================================
SET NOCOUNT ON;
USE [master];
GO
IF DB_ID(N'WabiBankPersonnelDB') IS NULL
    CREATE DATABASE [WabiBankPersonnelDB];
GO
IF SUSER_ID(N'wbpersonnel_owner') IS NULL
    CREATE LOGIN [wbpersonnel_owner] WITH PASSWORD = N'WbPersonnel#Owner#2026', DEFAULT_DATABASE = [WabiBankPersonnelDB], CHECK_POLICY = ON;
IF SUSER_ID(N'wbpersonnel_reader') IS NULL
    CREATE LOGIN [wbpersonnel_reader] WITH PASSWORD = N'WbPersonnel#Reader#2026', DEFAULT_DATABASE = [WabiBankPersonnelDB], CHECK_POLICY = ON;
GO
USE [WabiBankPersonnelDB];
GO
IF DATABASE_PRINCIPAL_ID(N'wbpersonnel_owner') IS NULL CREATE USER [wbpersonnel_owner] FOR LOGIN [wbpersonnel_owner];
ALTER ROLE db_owner ADD MEMBER [wbpersonnel_owner];
IF DATABASE_PRINCIPAL_ID(N'wbpersonnel_reader') IS NULL CREATE USER [wbpersonnel_reader] FOR LOGIN [wbpersonnel_reader];
ALTER ROLE db_datareader ADD MEMBER [wbpersonnel_reader];
GO
-- Deterministic pseudo-random numbers for the generators: gen.Rand(key) returns R1..R16, floats in [0, 1).
IF OBJECT_ID(N'gen.Rand') IS NOT NULL DROP FUNCTION gen.Rand;
IF SCHEMA_ID(N'gen') IS NULL EXEC (N'CREATE SCHEMA gen AUTHORIZATION dbo');
GO
CREATE FUNCTION gen.Rand (@key bigint)
RETURNS TABLE
WITH SCHEMABINDING
AS
RETURN
SELECT (CAST(CAST(SUBSTRING(h.A, 1, 4) AS int) AS bigint) + 2147483648) / 4294967296.0 AS R1,
       (CAST(CAST(SUBSTRING(h.A, 5, 4) AS int) AS bigint) + 2147483648) / 4294967296.0 AS R2,
       (CAST(CAST(SUBSTRING(h.A, 9, 4) AS int) AS bigint) + 2147483648) / 4294967296.0 AS R3,
       (CAST(CAST(SUBSTRING(h.A, 13, 4) AS int) AS bigint) + 2147483648) / 4294967296.0 AS R4,
       (CAST(CAST(SUBSTRING(h.A, 17, 4) AS int) AS bigint) + 2147483648) / 4294967296.0 AS R5,
       (CAST(CAST(SUBSTRING(h.A, 21, 4) AS int) AS bigint) + 2147483648) / 4294967296.0 AS R6,
       (CAST(CAST(SUBSTRING(h.A, 25, 4) AS int) AS bigint) + 2147483648) / 4294967296.0 AS R7,
       (CAST(CAST(SUBSTRING(h.A, 29, 4) AS int) AS bigint) + 2147483648) / 4294967296.0 AS R8,
       (CAST(CAST(SUBSTRING(h.B, 1, 4) AS int) AS bigint) + 2147483648) / 4294967296.0 AS R9,
       (CAST(CAST(SUBSTRING(h.B, 5, 4) AS int) AS bigint) + 2147483648) / 4294967296.0 AS R10,
       (CAST(CAST(SUBSTRING(h.B, 9, 4) AS int) AS bigint) + 2147483648) / 4294967296.0 AS R11,
       (CAST(CAST(SUBSTRING(h.B, 13, 4) AS int) AS bigint) + 2147483648) / 4294967296.0 AS R12,
       (CAST(CAST(SUBSTRING(h.B, 17, 4) AS int) AS bigint) + 2147483648) / 4294967296.0 AS R13,
       (CAST(CAST(SUBSTRING(h.B, 21, 4) AS int) AS bigint) + 2147483648) / 4294967296.0 AS R14,
       (CAST(CAST(SUBSTRING(h.B, 25, 4) AS int) AS bigint) + 2147483648) / 4294967296.0 AS R15,
       (CAST(CAST(SUBSTRING(h.B, 29, 4) AS int) AS bigint) + 2147483648) / 4294967296.0 AS R16
FROM (SELECT HASHBYTES('SHA2_256', CONCAT(@key, ':a')) AS A, HASHBYTES('SHA2_256', CONCAT(@key, ':b')) AS B) h;
GO

DECLARE @DropFks nvarchar(max) = N'';
SELECT @DropFks += N'ALTER TABLE ' + QUOTENAME(OBJECT_SCHEMA_NAME(parent_object_id)) + N'.' + QUOTENAME(OBJECT_NAME(parent_object_id)) + N' DROP CONSTRAINT ' + QUOTENAME(name) + N';'
FROM sys.foreign_keys;
EXEC sys.sp_executesql @DropFks;
GO

