IF OBJECT_ID(N'dbo.LeaveTypes', N'U') IS NOT NULL DROP TABLE dbo.LeaveTypes;
IF OBJECT_ID(N'dbo.EmployeeMovements', N'U') IS NOT NULL DROP TABLE dbo.EmployeeMovements;
IF OBJECT_ID(N'dbo.Employees', N'U') IS NOT NULL DROP TABLE dbo.Employees;
IF OBJECT_ID(N'dbo.Shifts', N'U') IS NOT NULL DROP TABLE dbo.Shifts;
IF OBJECT_ID(N'dbo.PublicHolidays', N'U') IS NOT NULL DROP TABLE dbo.PublicHolidays;
IF OBJECT_ID(N'dbo.Positions', N'U') IS NOT NULL DROP TABLE dbo.Positions;
IF OBJECT_ID(N'dbo.JobGrades', N'U') IS NOT NULL DROP TABLE dbo.JobGrades;
